GRANT UPDATE(last_maintenance) ON public.sites TO authenticated;
CREATE POLICY "Owners and linked businesses record service dates" ON public.sites FOR UPDATE TO authenticated USING(public.can_read_site(id)) WITH CHECK(public.can_read_site(id));
CREATE FUNCTION public.validate_service_date() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.last_maintenance > current_date THEN RAISE EXCEPTION 'Maintenance date cannot be in the future'; END IF; IF NEW.last_maintenance < (NEW.data->>'installDate')::date THEN RAISE EXCEPTION 'Maintenance cannot precede installation'; END IF; IF NEW.last_maintenance IS DISTINCT FROM OLD.last_maintenance AND NEW.last_maintenance IS NOT NULL THEN NEW.data:=jsonb_set(NEW.data,'{serviceHistory}',COALESCE(NEW.data->'serviceHistory','[]'::jsonb)||jsonb_build_array(jsonb_build_object('date',NEW.last_maintenance,'what','Maintenance recorded','who','GridPulse account'))); END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_service_date BEFORE UPDATE ON public.sites FOR EACH ROW EXECUTE FUNCTION public.validate_service_date();